/// Transport behavior specs cover all core executor families.
/// 
/// Proves: testgen is wired to the shared transport behavior catalog
/// used to drive behavioral transport contract checks.
#[test]
fn test_transport_behavior_specs_cover_core_families() {
    if !guard_test("test_transport_behavior_specs_cover_core_families", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let specs = gunbc_ir::default_transport_behaviors();
    assert_eq!(specs.len(), 6, "transport behavior catalog should cover tcp/http/rest/file/shell/local");
    assert!(specs.iter().any(|s| matches!(s.transport, gunbc_ir::TransportKind::Tcp)), "missing tcp transport behavior spec");
    assert!(specs.iter().any(|s| matches!(s.transport, gunbc_ir::TransportKind::Http)), "missing http transport behavior spec");
    assert!(specs.iter().any(|s| matches!(s.transport, gunbc_ir::TransportKind::Rest)), "missing rest transport behavior spec");
    assert!(specs.iter().any(|s| matches!(s.transport, gunbc_ir::TransportKind::File)), "missing file transport behavior spec");
    assert!(specs.iter().any(|s| matches!(s.transport, gunbc_ir::TransportKind::Shell)), "missing shell transport behavior spec");
    let tcp = specs.iter().find(|s| matches!(s.transport, gunbc_ir::TransportKind::Tcp)).expect("tcp behavior spec should exist");
    assert!(tcp.field_routes.iter().any(|route| route.request_field == "read_timeout_ms" && route.operation == "set_read_timeout"), "tcp behavior spec should pin read_timeout_ms routing");
    assert!(tcp.field_routes.iter().any(|route| route.request_field == "write_timeout_ms" && route.operation == "set_write_timeout"), "tcp behavior spec should pin write_timeout_ms routing");
    let models = gunbc_ir::default_system_models();
    let contract_specs = gunbc_ir::derive_contract_test_specs(&models);
    assert!(!contract_specs.is_empty(), "system model contract specs should derive at least one test spec");
    assert!(contract_specs.iter().any(|s| matches!(s.phase, gunbc_ir::UpsertPhase::Check)), "derived contract specs should include check-phase coverage");
    let harnesses = gunbc_ir::generate_contract_test_harnesses(&contract_specs);
    assert_eq!(harnesses.len(), contract_specs.len(), "each contract test spec should render a harness signature");
    assert!(harnesses.iter().all(|h| h.starts_with("fn contract_")), "rendered harnesses should be generated contract function signatures");
}

