// =========================================================================
// Bucket C: Scenario Coverage
// =========================================================================

// N+1 scenarios: one success + one per-transport failure + guard toggles.
// 2 single-failure scenarios (one per transport executor).
// Full failure scenarios require per-transport failure mocks (Tier 0 infra).
// 

/// Happy path: all transports succeed.
/// 
/// Proves: workflow reaches terminal outputs with all transports mocked as success.
#[test]
fn test_scenario_all_succeed() {
    if !guard_test("test_scenario_all_succeed", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("tools/readme.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let log = execute_dag(&dag, ExecuteConfig { mode: ExecutionMode::DryRun(mock_spec().to_boundary_mocks()), ..Default::default() }).expect("all-succeed scenario should complete");
    let entry = log.get("execute_read_readme").expect("'execute_read_readme' should be in log");
    assert!(entry.was_intercepted || entry.outputs.values().all(|v| matches!(v, Value::Skipped)), "'execute_read_readme' should be intercepted or skipped in DryRun");
    let entry = log.get("execute_readme_transport").expect("'execute_readme_transport' should be in log");
    assert!(entry.was_intercepted || entry.outputs.values().all(|v| matches!(v, Value::Skipped)), "'execute_readme_transport' should be intercepted or skipped in DryRun");
}

/// Single failure: 'execute_read_readme' transport fails.
/// 
/// Proves: failure propagation semantics are consistent.
#[test]
fn test_scenario_execute_read_readme_fails() {
    if !guard_test("test_scenario_execute_read_readme_fails", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("tools/readme.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let mut mocks = mock_spec().to_boundary_mocks();
    // Inject failure at 'execute_read_readme'
    mocks.set_value("execute_read_readme", "response", Value::Str("<TRANSPORT_FAILURE>".to_string()));
    // Execution may succeed or fail depending on graph semantics;
    // the key property is that it doesn't crash/hang.
    let _result = execute_dag(&dag, ExecuteConfig { mode: ExecutionMode::DryRun(mocks), ..Default::default() });
}

