/// Skip propagation: 'execute_read_readme' returns Skipped → downstream handles it.
/// 
/// Proves: when a transport's output is Skipped, downstream nodes
/// either skip themselves (guarded) or process the Skipped value
/// without crashing.
#[test]
fn test_skip_propagation_execute_read_readme() {
    if !guard_test("test_skip_propagation_execute_read_readme", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("tools/readme.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let mut mocks = mock_spec().to_boundary_mocks();
    mocks.set_value("execute_read_readme", "response", Value::Skipped);
    let log = execute_dag(&dag, ExecuteConfig { mode: ExecutionMode::DryRun(mocks), ..Default::default() }).expect("skip propagation should not crash or hang");
    assert!(log.get("compare_readme_content").is_some(), "downstream 'compare_readme_content' should still appear in log");
}

